<?php
namespace App\Models;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany,HasOne};
final class Proposal extends Model{use HasUuids;protected$fillable=['tenant_id','quote_offer_id','party_id','proposal_number','status','disclosures','terms_snapshot','submitted_at','decided_at','version','disclosure_schema_version_id','created_by','attested_at'];protected function casts():array{return['disclosures'=>'array','terms_snapshot'=>'array','submitted_at'=>'datetime','decided_at'=>'datetime','attested_at'=>'datetime'];}public function tenant():BelongsTo{return$this->belongsTo(Tenant::class);}public function party():BelongsTo{return$this->belongsTo(Party::class);}public function offer():BelongsTo{return$this->belongsTo(QuoteOffer::class,'quote_offer_id');}public function disclosureSchema():BelongsTo{return$this->belongsTo(DisclosureSchemaVersion::class,'disclosure_schema_version_id');}public function disclosureResponse():HasOne{return$this->hasOne(ProposalDisclosureResponse::class);}public function documents():HasMany{return$this->hasMany(ProposalDocument::class);}public function underwritingCase():HasOne{return$this->hasOne(UnderwritingCase::class);}public function payments():HasMany{return$this->hasMany(PaymentIntentRecord::class);}}
